def relevant_strings(v):
    out=[]
    if isinstance(v,str):
        if ('rear' in v.lower() or 'route' in v.lower()) and ('ambig' in v.lower() or 'unseen' in v.lower() or 'source does not' in v.lower()):out.append(v)
    elif isinstance(v,dict):
        for x in v.values():out+=relevant_strings(x)
    elif isinstance(v,list):
        for x in v:out+=relevant_strings(x)
    return out
